"""
Cross validation helpers.

The only piece of this module which is still relevant with modern versions of
scikit-learn is :class:`DataWrapper`, which makes a :class:`pandas.DataFrame`
indexable the way sklearn's cross validation machinery expects.

The ``cross_val_score`` function and the ``GridSearchCV`` /
``RandomizedSearchCV`` classes are thin, deprecated shims kept for backwards
compatibility: with scikit-learn >= 0.16 you can simply use the sklearn
versions directly with a DataFrame.
"""
import warnings

from sklearn import model_selection

DEPRECATION_MSG = '''
    Custom cross-validation compatibility shims are no longer needed for
    scikit-learn>=0.16.0 and will be dropped in sklearn-pandas==2.0.
'''


class DataWrapper(object):
    """
    Wrap a pandas DataFrame so that positional indexing (as used by
    sklearn's cross validation helpers) works as expected.
    """

    def __init__(self, df):
        self.df = df

    def __len__(self):
        return len(self.df)

    def __getitem__(self, key):
        return self.df.iloc[key]


def cross_val_score(model, X, *args, **kwargs):
    warnings.warn(DEPRECATION_MSG, DeprecationWarning)
    X = DataWrapper(X)
    return model_selection.cross_val_score(model, X, *args, **kwargs)


class GridSearchCV(model_selection.GridSearchCV):
    def __init__(self, *args, **kwargs):
        warnings.warn(DEPRECATION_MSG, DeprecationWarning)
        super(GridSearchCV, self).__init__(*args, **kwargs)

    def fit(self, X, *params, **kwparams):
        return super(GridSearchCV, self).fit(
            DataWrapper(X), *params, **kwparams)

    def predict(self, X, *params, **kwparams):
        return super(GridSearchCV, self).predict(
            DataWrapper(X), *params, **kwparams)


try:
    class RandomizedSearchCV(model_selection.RandomizedSearchCV):
        def __init__(self, *args, **kwargs):
            warnings.warn(DEPRECATION_MSG, DeprecationWarning)
            super(RandomizedSearchCV, self).__init__(*args, **kwargs)

        def fit(self, X, *params, **kwparams):
            return super(RandomizedSearchCV, self).fit(
                DataWrapper(X), *params, **kwparams)

        def predict(self, X, *params, **kwparams):
            return super(RandomizedSearchCV, self).predict(
                DataWrapper(X), *params, **kwparams)
except AttributeError:  # pragma: no cover
    pass

